/*
 * A043639  Numbers whose base-10 representation has exactly 3 runs.
 * https://oeis.org/A043639
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the nth integer whose decimal representation has exactly
 *            * three runs (maximal consecutive identical digits). The
 *            sequence is * generated by enumerating, in increasing numeric
 *            order, all admissible * combinations of length, digit triple and
 *            run lengths
 * Range:     u8 n <= 45, u16 n <= 45, u32 n <= 45, u64 n <= 45, u128 n <= 45,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <limits.h>

static inline idx_t count_len(idx_t L)
{
    /* Count of 3‑run numbers with L decimal digits.
       count = 9 digits for d1 (1–9)
               * 9 digits for d2 (0–9, d2≠d1)
               * 9 digits for d3 (0–9, d3≠d2)
               * number of compositions of L into 3 positive parts
               = 729 * (L−1 choose 2) = 729 * (L-1)*(L-2)/2   */
    unsigned __int128 a = (unsigned __int128)(L - 1);
    unsigned __int128 b = (unsigned __int128)(L - 2);
    unsigned __int128 comb = a * b / 2;
    unsigned __int128 cnt  = (unsigned __int128)729 * comb;
    /* cnt can be larger than 64‑bit; for comparison with n we use 128‑bit */
    return (cnt > (unsigned __int128)UINT64_MAX) ? UINT64_MAX
                                                : (idx_t)cnt;
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* offset is 1; behavior for n<1 is irrelevant */

    /* Find the digit length L such that the nth number lies in the block
       of length L.  cum128 holds the number of 3‑run numbers with length
       strictly less than L. */
    unsigned __int128 cum128 = 0;
    idx_t L = 3;
    while (1) {
        unsigned __int128 cnt128 = (unsigned __int128)729 *
                                  (unsigned __int128)(L - 1) *
                                  (unsigned __int128)(L - 2) / 2;
        if (cum128 + cnt128 >= (unsigned __int128)n) break;
        cum128 += cnt128;
        ++L;
    }

    /* Index (1‑based) of the desired number within all numbers of length L. */
    idx_t k = (idx_t)(n - (idx_t)cum128);

    /* Enumerate all admissible combinations in sorted order and locate
       the k‑th one. */
    for (uint8_t d1 = 1; d1 <= 9; ++d1) {              /* leading digit (1–9) */
        for (uint8_t d2 = 0; d2 <= 9; ++d2) {          /* second run digit */
            if (d2 == d1) continue;
            for (uint8_t d3 = 0; d3 <= 9; ++d3) {      /* third run digit */
                if (d3 == d2) continue;
                for (idx_t l1 = 1; l1 <= L - 2; ++l1) {   /* length of first run */
                    for (idx_t l2 = 1; l2 <= L - l1 - 1; ++l2) {
                        /* l3 is determined by L, l1 and l2, always >=1 */
                        if (--k == 0) {
                            idx_t l3 = L - l1 - l2;
                            /* Build the number. */
                            seq_t val = 0;
                            for (idx_t i = 0; i < l1; ++i) val = val * 10 + (seq_t)d1;
                            for (idx_t i = 0; i < l2; ++i) val = val * 10 + (seq_t)d2;
                            for (idx_t i = 0; i < l3; ++i) val = val * 10 + (seq_t)d3;
                            return val;
                        }
                    }
                }
            }
        }
    }
    /* Should never reach here; fall back to 0. */
    return (seq_t)0;
}
